window.ATLAS_QUOTES = {"jdeida":{"https://ar.wikipedia.org/wiki/تحرير_طرابلس_(2011)":{"pre":"وبعدَ هذه الاشتباكات تمكن الثوار أخيراً من السَّيطرة بالكامل على أربع مناطق كبرى في شرق العاصمة، هيَ قاعدة معيتيقة الجوية ومناطق تاجوراء وفشلوم وبن عاشور، لكن في المُقابل دفعوا ثمناً للاستيلاء على هذه المناطق 123 قتيلاً في تاجوراء وَحدها.","hi":"وقد استطاعَ الثوار أيضاً خلال هذه الاشتباكات إطلاق سراح 500 معتقل من «سجن الجديدة»، بالإضافة إلى أسرهم 35 فرداً تابعين لكتائب القذافي.","post":"أما الزحف من الخارج فكان قد بدأ بالفعل من الزاوية وجبهة جنوب العاصمة، بالإضافة إلى جبهتها الشرقية. === 21 أغسطس === اندلعت الاشتباكات مرَّة أخرى في العاصمة يومَ الأحد 21 أغسطس.","t":"تحرير طرابلس (2011) (Arabic Wikipedia)","d":""}},"maktab":{"https://en.wikipedia.org/wiki/Maktab_al-Nasser_prison":{"pre":"","hi":"Maktab al-Nasser prison is a prison in the Abu Salim district of Tripoli, Libya.","post":"Prior to the fall of Muammar Gaddafi's government in the 2011 Libyan civil war, it served as a prison and office of the internal security agency.","t":"Maktab al-Nasser prison (Wikipedia)","d":""}},"ainzara":{"https://ar.wikipedia.org/wiki/تحرير_طرابلس_(2011)":{"pre":"وفي وقت لاحق دخلَ الثوار مقرَّ التلفزيون الليبي الرسمي، وتلا ذلك توقف بثه بشكل تام.","hi":"كما حرَّروا آلاف السجناء المحتجزين في «سجن عين زارة» خلال اليوم ذاته.","post":"وقد شنت كتائب القذافي هجوماً على الثوَّار المُتمركزين في الساحة الخضراء (ساحة الشهداء) يوم الإثنين، بعدَ مُضي يوم كامل على دخولهم إليها واحتفالهم بـ«سقوط القذافي».","t":"تحرير طرابلس (2011) (Arabic Wikipedia)","d":""}},"blackhorse":{"https://archive.org/details/jprs-report_jprs-75801":{"pre":"His assignment is to monitor the recruited Tunisian elements in the sabotage camps.","hi":"The refrac- tory elements are either banished or interned in the \"Black Horse\" prison on the Tripoli International Airport road or in a new prison established by Libyan intelligence 7 kilometers from Tripoli.","post":"This use of intimida- tion is a natural thing in Libya.","t":"Near East/North Africa Report No. 2124","d":"1980-06-02"}},"towisha":{"https://en.wikipedia.org/wiki/Detention_centres_in_Libya":{"pre":"A ministerial department reporting to the Interior Ministry was created in 2012.","hi":"Its mission includes overseeing detention conditions and integrating independent detention centres into the state-run system. === Intensification of migratory flows in Libya from 2013 === From the first half of 2013, the number of migrants arriving in Libya—and departing towards Europe—began to rise significantly.","post":"According to the Frontex agency, 31,500 people landed on Italian shores between January and September 2013, compared to around 10,000 for all of 2012.","t":"Detention centres in Libya (Wikipedia)","d":""}},"cso":{"https://en.wikipedia.org/wiki/Bin_Ashur":{"pre":"United States bombing in 1986 devastated the neighbourhood.","hi":"Eiji Tanaka, the Ambassador of Japan to Libya, speculated that the U.S. bombs were intended to reach the Central Security Organization behind the Embassy of France to Libya, which received damage. == References ==","post":"","t":"Bin Ashur","d":"2026-10-18"}},"as-bab":{"https://www.cia.gov/readingroom/document/cia-rdp91-00901r000500230008-3":{"pre":"The Joint Chiefs were known to be reluctant to use force aS a response to terrorism, and had been resisting White House staff entreaties to move a third air- craft carrier into the Mediterranean to buttress the two already on patrol.","hi":"The Joint Chiefs had claimed that at least three carriers and their strike force would be needed if Libya re- sponded to a bombing with its 500 fighter aircraft.","post":"Adding a third car- rier to the task force, the Joint Chiefs explained, would disrupt the schedule of leaves for seamen and pilots.","t":"TARGET QADDAFI","d":"1987-02-22"},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000706870020-5":{"pre":"","hi":"Declassified and Approved For Release 2011/12/19 : CIA-RDP90-00965R000706870020-5 WASHINGTCN POST 16 April 1986 U.S, siged Qaddafi Compound Alter Tracing Terror Message \".","post":"7a} E APPEARED Ge rat a a By Bob Woodward and Ratrick E.","t":"U.S. TARGETED QADDAFI COMPOUND AFTER TRACING TERROR MESSAGE","d":"1986-04-16"},"https://en.wikipedia.org/wiki/1986_United_States_bombing_of_Libya":{"pre":"","hi":"The United States Air Force (USAF), Navy, and Marine Corps carried out air strikes, code-named Operation El Dorado Canyon, against Libya on 15 April 1986 in retaliation for the West Berlin discotheque bombing ten days earlier, which U.S. president Ronald Reagan blamed on Libyan leader Muammar Gaddafi.","post":"There were 40 reported Libyan casualties; one U.S. plane was shot down.","t":"1986 United States bombing of Libya (Wikipedia)","d":""},"https://www.cia.gov/readingroom/document/cia-rdp94b00280r000700170001-3":{"pre":"Muammar Qaddafi has left his capital for a fortified refuge in the Libyan desert and may be wounded, U.S. intelligence sources told The Washington Times late last night.","hi":"There were reports of fighting be- tween rival military factions at two separate locations following a long- awaited television appearance by the Libyan leader — 48 hours after American air strikes on his country — in which he accused President Reagan and British Prime Minister Margaret Thatcher of “murdering children.” The intelligence sources said Col.","post":"Qaddafi left Tripoli for Sabha, a fort- ified oasis in southwest Libya.","t":"RIVAL FACTIONS FIGHTING IN 2 LOCATIONS IN LIBYA","d":"1986-04-23"}},"as-benashour":{"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000403730006-2":{"pre":"…re the command-and-control center and admin- istrative buildings of El-Azziziya Barracks in Tripoli, none of which were struck by bombs, as well as the military side of the Tripoli airport and a com- mando training site in the nearby port city of Sidi Bilal, which were hit by the other nine F-111's.","hi":"Also mistakenly hit by one F-111 assigned to attack the barracks was a heavily popu- lated residential area of Tripoli near the French Embassy.","post":"The shielded orders explain a series of strong denials after the bombing, especially by State Department officials, when it became clear that Qaddafi’s personal quarters had been a primary target.","t":"TARGET QADDAFI","d":"1987-02-22"},"https://en.wikipedia.org/wiki/1986_United_States_bombing_of_Libya":{"pre":"NATO E-3A AWACS aircraft flying out of Trapani air base in Italy provided airborne surveillance. === United States Navy === America was on station in the Gulf of Sidra, but Coral Sea was preparing to leave the Mediterranean, and made a high speed run from Naples through the Strait of Messina.","hi":"America's air group would strike targets in downtown Benghazi and provide fighter and suppression support for the USAF bombers, while Coral Sea's planes would strike the Benina airfield outside Benghazi and provide fighter and suppression support for the Navy bombers.","post":"About 01:00 America launched six A-6E TRAM Intruder strike aircraft with Mark 82 bombs against the Jamahiriyah Guard barracks and six A-7 Corsair II strike support aircraft.","t":"1986 United States bombing of Libya (Wikipedia)","d":""},"https://www.cia.gov/readingroom/document/cia-rdp94b00280r000700170001-3":{"pre":"He said President Reagan “has is- sued orders to his armed forces to kill our children.","hi":"We have not issued any orders to murder anybody’’ The attacks, which the United States said were targeted on five se- curity and military installations in Tripoli and the eastern Libyan city of Benghazi, also severely damaged a civilian neighborhood in Tripoli.","post":"Western diplomats said at least 100 people and probably many more were killed in Tripoli alone.","t":"RIVAL FACTIONS FIGHTING IN 2 LOCATIONS IN LIBYA","d":"1986-04-23"},"https://www.cia.gov/readingroom/document/cia-rdp91b00874r000200140004-2":{"pre":"…ould be directed to Chief, P5X1 25X1 ieee wit ae 40004-2 | keep thee © . ie tg ey Sanitized Copy Approved for Release 2011/08/26 : CIA-RDP91B00874R000200140004-2 25X11 Domestic reactions to the US strike confirm the extent to which Qadhafi's political position has eroded over the past several years.","hi":"According to press reports, the funeral Procession in Tripoli for those killed in the US strike attracted only several thousand marchers out of a ulation of about 900,000. pro-Qadhafi 29X1 demonstrations Since the strike--highly publicized by the Libyan | media~-have only been stage-managed by his radical Supporters and have lacked oF spontaneity and enthusiasm of previous ones 25X14 ff popular discontent with 25X1 Qadhafi--already high--has become more open since the US strike.","post":"Libyans are openly 25X1 Or wasting scarce Financial resources on ineffective weaponry.","t":"LIBYA: QADHAFI'S POLITICAL POSITION SINCE THE AIRSTRIKE","d":"1986-07-17"},"https://en.wikipedia.org/wiki/Tripoli,_Libya":{"pre":"On 15 April 1986, U.S.","hi":"President Ronald Reagan ordered major bombing raids, dubbed Operation El Dorado Canyon, against Tripoli and Benghazi, killing 45 Libyan military and government personnel as well as 15 civilians.","post":"This strike followed US interception of telex messages from Libya's East Berlin embassy suggesting the involvement of Libyan leader Muammar Gaddafi in a bomb explosion on 5 April in West Berlin's La Belle discothèque, a nightclub frequented by US servicemen.","t":"Tripoli, Libya (Wikipedia)","d":""}},"as-nato-bab":{"https://en.wikipedia.org/wiki/2011_military_intervention_in_Libya":{"pre":"21 March 2011: Obama sent a letter to the Speaker of the House of Representatives and the President Pro Tempore of the Senate claiming the actions were justified under the War Powers Resolution.","hi":"24 March 2011: In telephone negotiations, French foreign minister Alain Juppé agreed to let NATO take over all military operations on 29 March at the latest, allowing Turkey to veto strikes on Gaddafi's ground forces from that point forward.","post":"Later reports stated that NATO would take over enforcement of the no-fly zone and the arms embargo, but discussions were still underway about whether NATO would take over the protection of civilians mission.","t":"2011 military intervention in Libya (Wikipedia)","d":""}},"bt-1979-embassy":{"https://en.wikipedia.org/wiki/1979_U.S._Embassy_Burning_in_Libya":{"pre":"On 2 December 1979, the U.S.","hi":"Embassy in Tripoli, Libya, was burned during protests over allegations that the United States was involved in the Grand Mosque seizure in Mecca, Saudi Arabia.","post":"The United States had already withdrawn the U.S.","t":"1979 U.S. Embassy Burning in Libya (Wikipedia)","d":""},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000302640078-5":{"pre":"…ged Ameri- cans to leave Libya, but there was no ef- tort to make it compulsory. | ing the crisis over the American hostages in Iran, the United States. banned the import of Iranian oil, froze’ Iran’s assets in this country, broke dip. lomatic relations and forbade most | Americans totravel to Iran.","hi":"Ofticially, the United States still has diplomatic relations with Libya, but all | American diplomats left Tripoli, the capital, in 1980 after a mob burned dora. the American Embassy.","post":"STAT Embargo on Oil Imports Weighed State Department officials said that on Americans’ living in or traveling to that country. ig Presently, some 1,500 ‘Americans, al. most all of thern in the oil industry, are employed in Libya.","t":"REAGAN WEIGHS ECONOMIC STEPS AGAINST LIBYANS","d":"1981-12-08"},"https://www.cia.gov/readingroom/document/cia-rdp90-00552r000100990092-3":{"pre":"Billy Car-: ter’s,.relations.; with . the Libyans?-.... ‘I Jease the. hostages.- “Our -relations were very ale ‘then; ** one official said,’ and Brzezin- 4 (‘ski felt that using Carter would dem- | -onstrate to the Libyans that he want: | bes to make a. serious proposition.","hi":"Meets Five days after the Brzezinski-Car- : ter-Houderi meeting; mobs in Tripoli + -burned the American Embassy there. | It was sometime after that incident * that Qaddafi asked Khomeini to re-: : “a wieaede ke ee f ie a tad «ie Approved For Release 2010/06/24 : CIA-RDP90-00552R000100990092-3 WADHLNULUIN FruolL 23 JULY 1980 The explanation that Brzezinski ini-? tiated this meeting by calling Billy: Carter was disputed’ yesterday by a: government official who was intimate- ly involved in the early diplomatic ef- forts to free the American hostages.","post":"This source, who had: heard of Brze- zinski’s dealings with Billy Carter and the Libyan charge- many months be- fore -yesterday’s. announcement, told The Washington Post that it was Billy Carter who asked Brzezinski to: meet, and not the other way around.","t":"BILLY CARTER USED BY BRZEZINSKI AS LIBYA GO-BETWEEN","d":"1980-07-23"}},"bt-1984-bab":{"https://en.wikipedia.org/wiki/1984_Libyan_coup_attempt":{"pre":"Libyan officials later confirmed that these incidents were carried out by the very same group that mounted the May 8 attack.","hi":"The authorities responded with increased security measures, including the patrolling of city streets. == Attack == At approximately 7:00 a.m. on 8 May 1984, a group of 20 to 30 gunmen assaulted the Bab al-Azizia barracks on the southern outskirts of Tripoli, a heavily fortified compound protected by electrified fences, bunkers and guard towers that served as Gaddafi's residence.","post":"The attackers were armed with rocket-propelled grenades and automatic weapons.","t":"1984 Libyan coup attempt (Wikipedia)","d":""},"https://www.cia.gov/readingroom/document/cia-rdp90-00552r000505250009-7":{"pre":"Revolutionary guards now control the distribution of live ammunition at the bases, one well- placed diplomat said.","hi":"Diplomats say the Revolutionary Committees and Guards began to grow in numbers and influence shortly after 12 men attacked the Bab el-Azziziya barracks on May 8, 1984, in an attempt officers have resented the decline in their living standards due to a fall in Libyan income from $22 billion in 1980 ‘to between $8 billion and $8 billion last Colonel Ishkal had reportedly fa- vored slashing investments in other sectors to solve the economic crisis, which he saw as potentially destabiliz- ing within the military, diplomats gaid.","post":"But Colonel Qaddafi and Major Jal- loud, who now supervises both . the Revolutionary Guards and Revolution- ary Committees, have preferred to'use the economic crisis to speed up’ the revolution and to justify.drastic actions — such as increasing the role of the revolutionary vanguards ~- that might …","t":"LIBYAN MILITARY TERMED RESTIVE UNDER QADDAFI","d":"1986-01-14"},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000100120080-3":{"pre":"In fact, CIA insiders refer _ sardonically to the agents involved and their CIA, handler, who was transferred after the assassination attempt failed.","hi":"The world learned some confused details of the ~ attempt, which began to unravel on May 6, when. the leader of NFSL’s military wing, Ahmed Ibrahim, Ahwas, was caught and killed trying to infiltrate P Libya from Tunisia.","post":"Two days later, a five-hour gun . battle at the Bab Aziziya barracks, where Qaddafi often stays, ended in the death or capture of the NFSL rebels.","t":"CIA BACKED QADDAFI ASSASSINATION TRY","d":"1985-06-12"},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000100120021-8":{"pre":"But the agency really doesn’t have much choice; the right man turned it down.","hi":"Despite an executive order that seems to forbid it, the CIA trained and supported the National Front for the Salvation of Libya before, during and after its attempt to assassinate Qaddafi on May 8, 1984, The anti-Qaddafi group was slaughtered in a day-long battle less than a mile from the barracks where the dictator was holed up behind Soviet-made tanks and antiaircraft guns.","post":"The coup attempt was doomed before it started.","t":"QADDAFI RIVAL SPURNS CIA OVERTURES","d":"1985-11-08"},"https://archive.org/details/micro_IA1176909_0413":{"pre":"Reports from Rome spoke earlier about shooting in the Libyan capital earlier today.","hi":"Spokesman Blames ‘Arafat Loyalists NCO081739 Paris AFP in English 1735 GMT 8 May 84 [By Marie Jioannidis] [Text] Paris, May 8 (AFP) — Libyan forces today repulsed an armed commando attack on Libyan leader Colonel Mu‘ammar al-Qadhdhafi’s combined headquarters and residence here, kill- ing the attackers, diplomatic sources in Tripoli said contacted by telephone.","post":"The attack, which Libyan sources said was carried out by 13 people who entered the country from neighbouring Tunisia on Sunday, began at around 0630 GMT near the Al-‘Aziziyah barracks in central Tripoli, the sources said.","t":"FBIS Daily Report: Middle East & Africa, Vol. V No. 091, 9 May 1984","d":"1984-05-09"},"https://en.wikipedia.org/wiki/National_Front_for_the_Salvation_of_Libya":{"pre":"During the demonstration, shots were fired from the embassy into the group of protestors, striking eleven people, including one of the police officers controlling the demonstration, Yvonne Fletcher, who died shortly afterward.","hi":"Fletcher's murder quickly led to the severing of diplomatic relations between Britain and Libya. === Military action === Three weeks after the embassy protest, on 8 May 1984, NFSL commandos took part in an attack on Gaddafi's Bab al-Azizia compound in Tripoli, in an attempt to assassinate the Libyan leader.","post":"The attack was thwarted when the group's leader, Ahmed Ibrahim Ihwas, was captured when trying to enter Libya at the Tunisian border.","t":"National Front for the Salvation of Libya (Wikipedia)","d":""},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000706950014-3":{"pre":"But the agency really doesn’t have much choice; the right man turned it down.","hi":"Despite an executive order that seems to forbid it, the CIA trained and supported the National Front for the Salvation of Libya before, during and after its attempt to assassinate Qaddafi on May 8, 1984.","post":"The anti-Qaddafi group was slaughtered in a day-long battle less than a mile from the barracks where the dictator was holed up behind Soviet-made tanks and antiaircraft guns.","t":"QADDAFI RIVAL SPURNS CIA OVERTURES","d":"1985-11-08"},"https://www.cia.gov/readingroom/document/cia-rdp88t00096r000600750001-4":{"pre":"In April 1984 the NFSL had infiltrated into Libya three commando teams totaling about 30 men.","hi":"At least half of this group was lost in the gunbattle with security forces in May 1984, including the founder and leader of the Salvation Forces, Ahmad Ahwas.","post":"Any survivors al- most certainly fled to avoid being discovered in the broad security sweeps that followed.","t":"LIBYAN OPPOSITION GROUPS: MUCH SOUND, LITTLE FURY","d":"1987-05-01"}},"bt-2011-uprising":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Tripoli residents barricaded their streets and districts with burning tires, joining up with other anti-government opponents.","hi":"The uprisings quickly spread through Tripoli, notably the neighbourhoods of Fashloum, Souq al Jum'aa, Tajura and Ben Ashur, and continued throughout the rest of the city.","post":"That night, heavy fighting was reported in the neighbourhoods of Suq al Jum'a, Arrada street and 20th of Ramdan street (formerly known as 11 June Street), while anti-Gaddafi locals closed off the major Alsika street.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-tajoura":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Al Arabiya and Al Jazeera both reported that the uprising continued as of the early morning; many rebels were reported dead in the district of Qadah, while the Mitiga International Airport was reportedly surrounded by rebel forces, who attempted to obtain its surrender.","hi":"The entire Tajura district was captured by rebel forces, while fighting in Suk al-Juma, Araba district and Mitiga International Airport continued.","post":"A rebel representative stated that the operation was \"going easily\", with the end target being Gaddafi's Bab al-Azizia compound.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-mitiga":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Boats from Misrata and Zliten carrying rebel forces and arms landed in Tripoli in the early morning, joining rebels within the city in the fight.","hi":"Following the rebel amphibious landing, they advanced towards the Mitiga airbase.","post":"Al Arabiya and Al Jazeera both reported that the uprising continued as of the early morning; many rebels were reported dead in the district of Qadah, while the Mitiga International Airport was reportedly surrounded by rebel forces, who attempted to obtain its surrender.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-green":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"However, it was reported later that Muhammad escaped from house arrest the next day with the aid of loyalist forces.","hi":"When the Libyana telephone company building was taken by the Tripoli Brigade, they sent out the following text message to the people of Tripoli : God is Great, We congratulate the people of Libya on the fall of the Gaddafi regime. === 22 August === By 1 am Tripoli time, rebels stated that 90% of Tripoli had been captured, including Green Square in central Tripoli.","post":"Al Jazeera and the BBC News, among other news stations, all reported and confirmed that opposition fighters had entered Green Square.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-bab":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Rebels also vandalised other statues of Gaddafi.","hi":"Following the assault on Gaddafi's compound France 24 TV reported that the Tripoli Brigade had sixty men killed in Tripoli during the previous 48 hours. === 24 August === Around noon, there were reports of fighting within the inner sanctum of the Bab al-Azizia compound, as snipers reportedly hiding in trees in the recreational area of the compound were still present.","post":"The rebels, meeting fierce resistance, continued to use heavy weaponry to expose loyalists and destroy fortifications in the centre of the compound.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-abusalim":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Reporters from inside the hotel reported that Gaddafi loyalists prevented them from leaving the compound, effectively taking them hostage amid gunfire from snipers and dwindling food supplies.","hi":"Fighting was also continuing in the Abu Salim district, which the rebels claimed to have captured the previous day, and later it was reported that loyalists were still in control of the area, as well as the al-Hadhba district.","post":"Around 5 pm, Tripoli time, all foreign reporters and staff that had been restricted to within the Rixos Al Nasr hotel were able to leave the compound in four vans of the Red Cross.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-airport":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"It was confirmed that rebel forces had been in full control of Tripoli International Airport for four days, and that Gaddafi's personal planes were still on the ground.","hi":"Despite the airport being secure, clashes were still ongoing on the road near the airport.","post":"The NTC announced full amnesty to anyone close to Gaddafi who killed or captured him.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"mk-sharshatt":{"https://en.wikipedia.org/wiki/Battle_and_massacre_at_Shar_al-Shatt":{"pre":"","hi":"The battle and massacre at Shar al-Shatt (Arabic: شارع الشط Shār’ ash-Shaṭ; Sciara Sciat in Italian) occurred on 23 October 1911 in the village of Shar al-Shatt on the outskirts of Tripoli, Libya during the Italo-Turkish War.","post":"503 Italians were killed in Shar al -Shatt, 290 of which in the following massacre of soldiers who had surrendered.","t":"Battle and massacre at Shar al-Shatt (Wikipedia)","d":""}},"mk-riots":{"https://en.wikipedia.org/wiki/1945_anti-Jewish_riots_in_Tripolitania":{"pre":"The 1945 anti-Jewish riots in Tripolitania were the most violent riots against Jews in North Africa in the 20th century.","hi":"From November 5 to November 7, 1945, more than 140 Jews were killed and many more injured in a pogrom in Tripolitania, then under British military occupation.","post":"38 Jews were killed in Tripoli from where the riots spread.","t":"1945 anti-Jewish riots in Tripolitania (Wikipedia)","d":""}},"bt-2014-airport":{"https://en.wikipedia.org/wiki/Tripoli_International_Airport":{"pre":"It was expected to be completed in 2024, however due to Libya failing to keep up with payments the Italian firms delayed construction in October 2024 before the project was transferred to a Libyan contractor.","hi":"The first asphalt layer of the runway was reportedly laid in September 2025. == Airlines and destinations == As of July 2014, all passenger flights into Tripoli use Mitiga International Airport; all scheduled cargo operations into Tripoli International Airport have also ceased. == Accidents and incidents == On 9 May 1944, a Douglas Dakota III (KG548) of the RAF crashed and burned on takeoff during its delivery flight when the undercarriage retracted.","post":"It is unknown if anyone died.","t":"Tripoli International Airport (Wikipedia)","d":""}},"bt-2018":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2018)":{"pre":"","hi":"The Battle of Tripoli was a series of clashes in Tripoli, Libya from 27 August to 25 September 2018 during the Second Libyan Civil War.","post":"It was fought between several militias and was ended by a ceasefire. == Prelude == Clashes between militias broke out in Tripoli from 26 to 27 August 2018, touching off renewed fighting in the city after 18 months of relative calm.","t":"Battle of Tripoli (2018) (Wikipedia)","d":""}},"bt-2025":{"https://en.wikipedia.org/wiki/2025_Tripoli_clashes":{"pre":"","hi":"On 12 May 2025, clashes broke out in Tripoli, Libya, between the 444th Infantry Brigade and the Stability Support Apparatus (SSA).","post":"The fighting began after SSA commander Abdel Ghani al-Kikli was assassinated.","t":"2025 Tripoli clashes (Wikipedia)","d":""}},"mk-yarmuk-2011":{"https://en.wikipedia.org/wiki/Yarmuk_massacre":{"pre":"In total, 124 people were killed at the site. == Background information == During the final stages of the Libyan Civil War, which erupted in February 2011, forces loyal to Muammar Gaddafi engaged in brutal crackdowns against rebel groups seeking to overthrow his regime.","hi":"The Khamis Brigade, led by Gaddafis son Khamis, was known for its involvement in violent suppression tactics. == The massacre == On August 23, 2011, detainees were held in a warehouse located in the Khalida Ferjan neighborhood in Salahaddin, south of Tripoli, adjacent to the Yarmuk Military Base.","post":"The detainees, numbering approximately 153, were almost entirely civilians.","t":"Yarmuk massacre (Wikipedia)","d":""}},"mk-qasr-2011":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"CNN reported a \"fierce firefight in one corner of Muammar Gaddafi's compound\" at about 2:00 local time.","hi":"Reuters reported that rebels stormed the Abu Salim district after a NATO airstrike. === 26 August === At Khilit al-Ferjan and Qasr bin Ghashir, two loyalist camps in the Tripoli area, loyalists killed \"numerous detainees\", according to eyewitnesses.","post":"Grenades and gunfire were used on a large group of prisoners after about 160 escaped from a metal hangar.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-1980-embassies":{"https://archive.org/details/micro_IA1176908_0539":{"pre":"No damage was caused to the embassy.","hi":"FRENCH AMBASSADOR COMMENTS ON FRENCH EMBASSY INCIDENT IpD042306 Paris Domestic Service in French 1800 GmT 4 Feb 80 ID [Text] [Announcer] This morning it was every man for himself at the French Embassy in Libyae The building was suddenly attacked by demonstrators and the premises ransacked.","post":"These very violent incidents are, without any doubt, connected with the Qafsah events.","t":"FBIS Daily Report: Middle East & N. Africa, Vol. V No. 025, 5 February 1980","d":"1980-02-05"},"https://archive.org/details/micro_IA1176909_0354":{"pre":"OCR text: errors are likely.","hi":"LIBYA Demonstrations Reported at Jordanian Embassy LD182129 Tripoli JANA in English 1845 GMT 18 Feb 84 [Text] Tripoli, Jumada al Awal 14, Feb 18, JAMAHIRIYAH NEWS AGENCY — wiasses of Palestinians and other Arabs demonstrated here this morning to condemn the visit by the head of the Egyptian regime and King Husayn of Jordan to Washing- ton and their meeting of conspiracy with the head of the U.S.","post":"Administration Ronald Reagan to undermine the Palestinian cause.","t":"FBIS Daily Report: Middle East & Africa, Vol. V No. 035, 21 February 1984","d":"1984-02-21"},"https://www.cia.gov/readingroom/document/cia-rdp90t00114r000800810001-1":{"pre":"Two gunmen kill an anti-Qadhafi Libyan journalist.","hi":"Tunisian and French Embassies in Tripoli sacked and burned by a mob while Libyan authorities took no action. j Declassified in Part - Sanitized Copy Approved for Release 2012/02/17 : CIA-RDP90T00114R000800810001-1","post":"","t":"LIBYAN INVOLVEMENT IN TERRORISM","d":"1986-01-01"},"https://archive.org/details/micro_IA1176908_0673":{"pre":"2.","hi":"We deeply regret the dishonourable stand taken by the British authorities against the people's bureau and have to tell them: ‘We are not honoured to deal with a foreign office who takes decision on the basis of press reports without confirming the authenticity of such reports. [Signed] The people's bureau of the Jamahiriyah UK EMBASSY IN TRIPOLI FIREBOMBED 13 JUNE LD142230 LONDON PRESS ASSOCIATION in English 1854 GMT 14 Jun 80 [By David Healey, PRESS ASSOCIATION diplomatic staff] [Text] A firebomb was thrown into the British Embassy in Tripoli, Libya, on Friday night it was confirmed tonight by the Foreign Office in London.","post":"The bomb was a small one and caused only superficial damage to a wooden entrance door.","t":"FBIS Daily Report: Middle East & Africa, Vol. V No. 117, 16 June 1980","d":"1980-06-16"},"https://archive.org/details/jprs-report_jprs-82924":{"pre":"Mm amir. ‘Mare Kravetz dispatch: \"Libya: Colonel al-Qadhdhafi's Green Diplomacy\" } (Excerpts} Franco-Libyan relations, which have officially improved, could herald a radical change in Colonel al-Qadhdhafi's diplomacy.","hi":"The man who andes terrorism and now claims to be leader of the \"green movement\" and pacifism in the world is wondering whether something new in happening in the west. indeed, the bad relations with Giscard and the untimely remarks have been for- The French Embassy in Tripoli, sacked and burned on 4 February 1980 rollowing the GAFSA events, has meanwhile been entirely rebuilt by the Libyan authorities.","post":"A new ambassador, Christian Graff, who is particularly au fait with regional matters, especially the Chad question, has been instailed in it with a dynamic team anxious to pursue an open and attentive diplomacy. gotten.","t":"Near East/North Africa Report No. 2712","d":"1983-02-23"},"https://archive.org/details/micro_IA1176909_0357":{"pre":"OCR text: errors are likely.","hi":"LIBYA Government Reacts to Jordan’s Severance of Ties King Husayn’s Policies Scored LD231844 Tripoli Domestic Service in Arabic 1330 GMT 23 Feb 84 [Text] Yesterday, the Jordanian regime announced the severance of its political relations with the Jamahiriyah on the pretext of a demonstration staged by the Arabs residing in the Jamahiriyyah outside the Jordanian Embassy in Tripoli.","post":"The demonstration was held to protest the capitulatory trend in Jordanian policy, which has become more definite since the recent visit of King Husayn to Washington and his meetings with the U.S. and Egyptian presidents.","t":"FBIS Daily Report: Middle East & Africa, Vol. V No. 038, 24 February 1984","d":"1984-02-24"},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000807600015-8":{"pre":"","hi":"\\ Declassified in Part - Saniiees Copy Approved for Release 2012/01/23 : CIA-RDP90-00965R000807600015-8 Se: ore snTeRe Ty ? | Declassified in Part - Sanitized Copy Approved for Release 2012/01/23 : CIA-RDP90-00965R000807600015-8 WASHINGTON POST 23 April 1984 Hangings in Tripoli Focus By Bob Woodward Washington Post Staff Writer TRIPOLI, Libya, April 22—A week ago today the Student Rev- olutionary Committee, which en- sures that Libyan leader Col.","post":"Muammar Qaddafi’s revolution- — ‘ary principles are scrupulously adhered to among Tripoli Uni- versity’s 27,000 students, an- nounced that two students would be publicly hanged for treason.","t":"HANGINGS IN TRIPOLI FOCUS ATENTION ON LIBYAN DISSENT","d":"1984-04-23"}},"bt-1985-port-bomb":{"https://www.cia.gov/readingroom/document/05632817":{"pre":"In June, several Prima Linea leaders met with Red Brigades’ members in Naples—possibly to coordinate the robbery.","hi":"Possible Assassination Attempt Against Qadhafi a car bomb exploded on 14 September near the site of an economic fair in Tripoli, destroying a warehouse.","post":"Libyan leader Mu‘ammar Qadhafi reportedly was scheduled to attend the fair.","t":"TERRORISM REVIEW","d":"1985-10-07"},"https://www.cia.gov/readingroom/document/cia-rdp91b00874r000200080011-1":{"pre":"Shortages of food, water, and electricity have become a way of life for most Libyans; what is available is often expensive.","hi":"Rising Discontent Public discontent has been more open this past year, and includes instances of violence. -- There was at least one attempt to assassinate Qadhafi early in 1985; a car bomb explosion in the Tripoli port area last September also may have been aimed at Qadhafi. -- Qadhafi also has encountered growiny pressure from Libyan opposition groups, particularly the National Front for the Salvation of Libya (NFSL). -- By far the most ominous development for Qadhafi this past year is rising discontent in the armed forces. -- Qadhafi arrested scores of officers last March after discovering the first organized coup plot in two years.","post":"More officers were arrested in September, 25XK1 25X11 Sanitized Copy Approved for Release 2011/09/12 : CIA-RDP91B00874R00020008001 1-1 Sanitized Copy Approved for Release 2011/09/12 : CIA-RDP91B00874R00020008001 1-1 DISTRIBUTION: Copy 1 - DCI Copy 2 - DDI Copy 3 - NIO/NESA Copy 4 - NIO/CT Copy 5 - C…","t":"TALKING POINTS FOR THE DCI 14 JANUARY 1986 LIBYA: QADHAFI'S DOMESTIC POSITION","d":"1986-01-14"}},"bt-1985-bab-shooting":{"https://www.cia.gov/readingroom/document/cia-rdp05-01559r000400470002-2":{"pre":"Also, the public hanging of two Tripoli students was reported to have fu- eled open dissent among thousands _ of students forced to watch.","hi":"In 1985, a segment of the Libyan military reportedly launched two assassination attempts against Qad- dafi, who responded by executing dozens of officers.","post":"Staff researcher James Schwartz contributed to this report. .","t":"OFFICERS FEARED BY QADDAFI REPORTEDLY CLOSE","d":"1986-04-04"},"https://en.wikipedia.org/wiki/Muammar_Gaddafi":{"pre":"The first was a plot by conservative officers to assassinate him at a villa on the outskirts of Tripoli; the second was an assault on his convoy.","hi":"In November 1985, Colonel Hassan Ishkal, the third most powerful man in Libya, head of the military region of Sirte, died in a suspicious car accident.","post":"Ishkal's death was attributed to Jalloud, Khalifa Hunaysh or Gaddafi.","t":"Muammar Gaddafi (Wikipedia)","d":""}},"bt-2011-feb21":{"https://en.wikipedia.org/wiki/Timeline_of_the_2011_Libyan_civil_war_before_military_intervention":{"pre":"Protesters seized control of the oil town of Ra's Lanuf and workers set up committees to protect the oil installations.","hi":"Activists claimed that protesters surrounded Gaddafi's Bab al-Aziza compound and were trying to storm it, but were forced back by heavy gunfire that killed up to 80 people. === 22 February === Gaddafi made a brief appearance on Libyan state television in which he said he had been speaking to the youth in Tripoli's Green Square.","post":"He also said: I am in Tripoli.","t":"Timeline of the 2011 Libyan civil war before military intervention (Wikipedia)","d":""}},"bt-2012-abusalim":{"https://en.wikipedia.org/wiki/Factional_violence_in_Libya_(2011%E2%80%932014)":{"pre":"On 16 March, a pro-autonomy demonstration was held in Benghazi, which was attacked by unknown gunmen, leaving one person dead and five injured.","hi":"On 18 March, a clash erupted between the Zintan militia and residents of Tripoli's Abu Salim district, previously loyal to Gaddafi.","post":"One militiaman was killed before a cease-fire was brokered by the district's own militia commander.","t":"Factional violence in Libya (2011–2014)","d":"2026-10-18"}},"bt-2012-dahmani":{"https://en.wikipedia.org/wiki/Factional_violence_in_Libya_(2011%E2%80%932014)":{"pre":"The attackers have also blown up the mosque attached to it and its library, filmed the events and posted the footage online.","hi":"On 25 August, the Al-Shaab Al-Dahmani mosque and shrine in central Tripoli was bulldozed in broad daylight by a group of armed Salafists, including members of the security forces.","post":"According to witnesses, when the police came, they prevented people from approaching instead of stopping the demolition, while an anonymous government officer alleged that after a small clash they sealed the area to prevent violence from spreading.","t":"Factional violence in Libya (2011–2014)","d":"2026-10-18"}},"bt-2019-abusalim":{"https://en.wikipedia.org/wiki/Western_Libya_campaign":{"pre":"Images of al-Kikli's mutilated body circulated on social media.","hi":"During 15–17 April 2019, rocket attacks using inaccurate technology occurred against three densely populated residential areas in and near the Abu Salim area of Tripoli, and were interpreted by Amnesty International (AI) as \"unlawful attacks that could amount to war crimes\".","post":"Based on information from witnesses and satellite imaging, AI stated that those launching the rockets \"failed to take necessary precautions to protect civilian lives and civilian objects\".","t":"Western Libya campaign (Wikipedia)","d":""}},"bt-2019-yarmouk":{"https://en.wikipedia.org/wiki/Western_Libya_campaign":{"pre":"…ch is the only option he has left now anyway.\" Flights were temporarily suspended; by 9 April, a coalition of local and regional militias and GNA forces had pushed Hifter's forces from the airport, and flights resumed, with clashes continuing in multiple locations on the southern fringes of Tripoli.","hi":"On 8 April, the LGA said 19 of its soldiers died in recent days in the fighting in and around Tripoli, while a spokesman for the GNA's said that \"fighting in the south of the capital had killed at least 25 people, including fighters and civilians, and wounded 80.\" From the beginning of April 2019 to mid-May 2019, southern Tripoli's Yarmouk military camp/barracks had changed hands between the GNA and the LNA at least five times.","post":"The LNA used BM-21 Grad MRLs against GNA positions in retaliation for GNA airstrikes.","t":"Western Libya campaign (Wikipedia)","d":""}},"mk-sadr-1978":{"https://archive.org/details/micro_IA1176908_0500":{"pre":"The imam, Shaykh Muhammad Sha'ta Ya'qub and 'Abbas Badr were executed by Lieutenant Faraj Bughaliyah and four under-officers who misinterpreted an order, AL-MUHARRIR said, citing a reliable Arab source.","hi":"The newspaper, organ of the Socialist Union of Popular Forces, said Imam as-Sadr and his companions were executed on a firing range near Janzur, 30 kms (20 miles) from [fripoli.","post":"Ve.","t":"FBIS Daily Report: Middle East & N. Africa, Vol. V No. 237, 7 December 1979","d":"1979-12-07"}},"mk-suwani-1982":{"https://archive.org/details/jprs-report_jprs-82800":{"pre":"OCR text: errors are likely.","hi":"LIBYA EXECUTIONS FOLLOW UNREPORTED COUP ATTEMPT Cairo AL-JUMHURIYAH in Arabic 18 Dec 82 p l [Article by the Rome correspondent for AL-JUMHURIYAH: \"Execution of Four Officers in the Libyan Army Who Attempted a Coup\"] [Text] Libyan president Mu'ammar al-Qadhdhafi has executed four of the officers who staged an undisclosed coup attempt.","post":"The executions took place in a villa belonging to Idris al-Sanusi, former king of Libya, at the Suwani bin Yadim cattle farm located 20 miles south of the city of Tripoli, which Libyan intelligence uses for interrogation and torture purposes.","t":"Near East/North Africa Report No. 2701","d":"1983-02-03"},"https://archive.org/details/micro_IA1176909_0025":{"pre":"The brother leader called on the conferees to safeguard and maintain the conference annually and to achieve further positive results in the interests of the Arab citizen.","hi":"100 ARRESTED IN FOILED ATTACK ON AL-QADHDHAFI NC171047 Paris AFP in English 0945 GMT 17 Nov 82 [Text] Paris, Nov 17 (AFP) -- Some 100 Libyan military and security officers were reportedly arrested early this month as they were preparing to attack a plane carrying Libyan leader Mu'ammar al-Qadhdhafi, a London-based Arabic language news- paper reported today.","post":"The paper, ASH-SHARQ A’ AWSAT, said the attack, planned for November 4 when Colonel al-Qadhdhafi was scheduled to return from a visit to Yugoslavia, was foiled when one of the officers alerted loyalist security forces who captured the plotters hours before the plane was due to arrive.","t":"FBIS Daily Report: Middle East & Africa, Vol. V No. 223, 18 November 1982","d":"1982-11-18"}},"mk-gargaresh-2011":{"https://en.wikipedia.org/wiki/Khamis_Brigade":{"pre":"On 23 August 2011, the Khamis Brigade killed around 50 prisoners in a Tripoli warehouse and then set fire to the warehouse.","hi":"On 29 August 2011, Khamis Gaddafi was killed in fighting in Tarhuna, On 9 September, the NTC health minister said that the Khamis Brigade had lost around 9,000 soldiers during the war, it is unknown who may have commanded remnants of the Khamis Brigade in the closing days of the 2011 Libyan civil war. == See also == 4th Armoured Division (Syria) Republican Guard (Syria) == References == == External links == Khamis Army Shoots One In The Head\", vspahi, 2011-02-18 (YouTube) \"Wounded Soldier of Khamis (Gadhafi's Son) LIBYA\", MeddiTV, 2011-02-18 (YouTube) Joshi, Shashank (22 August 2011).","post":"\"Analysis: Why Gaddafi's crack troops melted away\".","t":"Khamis Brigade (Wikipedia)","d":""}},"mk-janzour-2012":{"https://en.wikipedia.org/wiki/Factional_violence_in_Libya_(2011%E2%80%932014)":{"pre":"Bani Walid clashes Uprising started in Bani Walid on 23 January 2012 due to an incident in the city of Bani Walid in which the \"May 28 Brigade\" militia wished to arrest local men in unclear circumstances.","hi":"The May 28 Brigade and their compound were then attacked by local fighters who then took control of the town. ==== February 2012 ==== On 6 February, seven male black Libyan civilians from Tawergha were killed by militias who raided their makeshift refugee camp at a former naval academy in Janzour, a suburb of Tripoli.","post":"The survivors said that they appeared to be from Misrata because of their license plates, though the Misrata militia denied this.","t":"Factional violence in Libya (2011–2014)","d":"2026-10-18"}},"mk-corinthia-2015":{"https://en.wikipedia.org/wiki/Corinthia_Hotel_Tripoli":{"pre":"It is run by the Maltese Corinthia Hotels International (CHI) plc hotels management company.","hi":"The hotel was opened in 2003 by Prime Minister, Shukri Ghanem [More information required]. == 2015 terror attack == On 27 January 2015 ten people, including five foreigners from France, Italy, Turkey, United Kingdom and the American Crucible LLC security contractor David Berry, were killed in a gun attack.","post":"Prior to this attack, six people were injured in a car bomb explosion near the hotel.","t":"Corinthia Hotel Tripoli (Wikipedia)","d":""}},"as-nato-khamis":{"https://en.wikipedia.org/wiki/Khamis_Brigade":{"pre":"Another report stated that officers at the air force school had mutinied and the adjacent air force base had been overwhelmed.","hi":"On 18 April, the headquarters of the Khamis Brigade near Tripoli was bombed and destroyed by NATO planes that took part in the 2011 military intervention in Libya.","post":"According to NATO sources, the headquarters had been used to coordinate and lead attacks on civilians.","t":"Khamis Brigade (Wikipedia)","d":""}},"palace":{"https://en.wikipedia.org/wiki/Idris_of_Libya":{"pre":"The new constitution granted Idris significant personal power, and he remained a crucial player in the country's political system.","hi":"Idris ruled via a palace cabinet, namely his royal diwan, which contained a chef de cabinet, two deputies, and senior advisers.","post":"This diwan worked in consultation with the federal government to determine the policies of the Libyan state.","t":"Idris of Libya (Wikipedia)","d":""}},"green":{"https://en.wikipedia.org/wiki/Martyrs%27_Square,_Tripoli":{"pre":"","hi":"The Martyrs' Square (Arabic: ميدان الشهداء Maydān ash-Shuhadā'), known as Green Square (الساحة الخضراء as-Sāḥah al-Khaḍrā') under the Gaddafi government, Independence Square (ميدان الاستقلال Maydān al-Istiqlāl) during the monarchy, and originally (during Italian colonial rule) known as Piazza Italia (\"Italy Square\"), is a downtown landmark at the bay in the city of Tripoli, Libya.","post":"The main commercial center of the city surrounds the square.","t":"Martyrs' Square, Tripoli (Wikipedia)","d":""}},"fateh":{"https://www.cia.gov/readingroom/document/cia-rdp05-01559r000400370055-5":{"pre":"We are determined not to lay down our arms until the revolutionary program which will transfer the Libyan people from the state of backwardness to the state of progress is achieved.","hi":"PURGE PANEL FORMED IN FORMER TRIPOLI UNIVERSITY Tripoli ARNA in Arabic 1030 GMT 12 Apr 76 LD [Text] Tripoli, 12 April--The central revolutionary, committee was formed yesterday at Al- Fatih University, formerly Tripoli University.","post":"The committee includes students, teachers, workers and employees.","t":"AL QADHDHAFIE ADDRESSES CROWD AT RCC BUIDLING","d":"1976-04-12"},"https://archive.org/details/ufiche-test-document_jprs-82358":{"pre":"There is absolutely no security; the economy has collapsed; the treasury is bankrupt; members of the military are always grumbling and constantly subject to physical elimination; and chaos has become prevalent everywhere.","hi":"News has been received that al-Qadhdhafi recently arrested more than 400 university students and faculty members in Tripoli and Benghazi last April ?. ‘‘o one can believe that a country like Libya whose population is no more than 3 million persons and whose annual revenues from oil is in excess of 25 billion dollars can find itself bankrupt.","post":"No one can believe that the government would issue an order forbidding the importation of more than 83 important goods-—-and some of these are basic goods--because it Cannot pay for its imports.","t":"Near East/North Africa Report No. 2669","d":"1982-12-01"},"https://en.wikipedia.org/wiki/University_of_Tripoli":{"pre":"The university was the site of a student uprising by the Students' Union (SU) during the August 2011 Battle of Tripoli, part of the 2011 Libyan Civil War.","hi":"In 2012, the university was renamed from al-Fateh University to the original name of University of Tripoli. == Political importance == After the 1969 coup by Gaddafi, Tripoli and Benghazi universities were subjected to a crackdown by the Gaddafi government.","post":"From the early 1970s political activity was severely curtailed and by the late 1970s, Gaddafi instructed his followers to arrest any students or staff members who were vocally resistant to his government.","t":"University of Tripoli (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/1976_Libyan_protests":{"pre":"","hi":"The 1976 Libyan protests were demonstrations organized by university students in Tripoli and Benghazi who protested against human rights violations and military control over the civilian population, calling for free and fair elections and for a civilian government.","post":"The protests were repressed and many students were imprisoned. == Background == Muammar Gaddafi became the de facto leader of Libya on 1 September 1969 after leading a group of young Libyan Army officers against King Idris I in a bloodless coup d'état.","t":"1976 Libyan protests (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Human_rights_in_Libya_under_Muammar_Gaddafi":{"pre":"This included extrajudicial killings, public executions, ethnic cleansing, and the torture of civilians.","hi":"During the Libyan Civil War in 2011, Gaddafi's forces killed allegedly unarmed protestors and indiscriminately bombed civilian areas, drawing condemnation from human rights organizations. == Student protests == On April 7, 1976, university students throughout Libya protested against human rights violations and authoritarian military control over all aspects of civilian lives.","post":"Protesters called for free and fair elections to take place and a more democratic system to be implemented in Libya.","t":"Human rights in Libya under Muammar Gaddafi (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/1984_Libyan_coup_attempt":{"pre":"The UK severed diplomatic ties with Libya, and the incident fueled mutual accusations.","hi":"Diplomats reported growing dissatisfaction within Libya over economic difficulties, the public hangings of two dissident students at Al Fateh University, and the increasing influence of revolutionary committees.","post":"In the weeks preceding the coup attempt, a series of sabotage operations struck Libya.","t":"1984 Libyan coup attempt (Wikipedia)","d":""}},"mk-jan1976":{"https://ar.wikipedia.org/wiki/%D8%AA%D8%A7%D8%B1%D9%8A%D8%AE_%D9%84%D9%8A%D8%A8%D9%8A%D8%A7_%D8%A7%D9%84%D9%85%D8%B9%D8%A7%D8%B5%D8%B1":{"pre":"…لتي ارتكبتها عناصر قوى الثورة، فقام الطلاب بالسيطرة على الأوضاع في الجامعة ثم قام الطلاب في اليوم التالي بالتظاهر وسط المدينة في بنغازي ولكن بعد ساعات من السير في الشوارع، حاصرت قوات الحرس الجمهوري الطلبة المتظاهرين من كل جانب وأطلقوا النار عليهم مما أدى إلى سقوط طالب ووفاة آخر في المستشفى فيما بعد.","hi":"ما أن انتشرت الإخبار حول الصدام الذي تم بين طلبة جامعة بنغازي وقوى الثورة وعناصر الأمن حتى عمّت مظاهرات التنديد كليات طرابلس وبعض المدارس والمعاهد، وذلك في السادس من يناير 76.","post":"فقامت الحكومة في نفس اليوم بإخراج مسيرات تأييد من قوى الثورة الذين بيّنوا أنهم على أتم الاستعداد للمواجهة المسلحة.","t":"تاريخ ليبيا المعاصر (Arabic Wikipedia)","d":""},"http://countrystudies.us/libya/76.htm":{"pre":"Seventeen years after the Qadhafi-led coup, students as a whole remained divided between supporters and critics of the revolutionary regime.","hi":"A particularly serious incident occurred in January 1976 when students at the University of Benghazi protested government interference in student union elections.","post":"Elected students who were not ASU members were considered officially unacceptable by the authorities.","t":"Libya - OPPOSITION TO QADHAFI","d":"1987"}},"mk-april1976":{"https://www.cia.gov/readingroom/document/cia-rdp05-01559r000400370064-5":{"pre":"For it cannot have been far from the colonel's mind that, only a few days before, fierce student clashes had taken Place in the universities of Tripoli and Benghazi, though in present-day Libya no public mention is made of such events.","hi":"At Benghazi students marched through the streets shouting slogans like, \"Al-Qadhdhafi, the mad one...all your people are kept in prison.\" Even more offensively they cried, \"It is better in hell with Idris than in heaven with Al-Qadhdhafi,\" a fine example of how Arab slogans move into the fieldofhyperbole, for no-one seriously wants the return of King Idris.","post":"The Prime Minister Drew His Revolver Squads of police moved in, Discharging a hundred rounds of automatic rifle fire.","t":"BRITISH CORRESPONDENT INTERVIEWS AL-QADHDHAFI","d":"1976-05-02"},"https://en.wikipedia.org/wiki/1976_Libyan_protests":{"pre":"The protests were repressed and many students were imprisoned. == Background == Muammar Gaddafi became the de facto leader of Libya on 1 September 1969 after leading a group of young Libyan Army officers against King Idris I in a bloodless coup d'état.","hi":"After the king had fled the country, the Revolutionary Command Council (RCC) headed by Gaddafi abolished the monarchy and the old constitution and established the Libyan Arab Republic. == Protests == During the transition to the Jamahiriya, on 7 April 1976, students of universities in Tripoli and Benghazi protested against human rights violations and the military’s control over \"all aspects of life in Libya\"; the students called for free and fair elections to take place and for power to be transferred to a civilian government.","post":"Violent counter-demonstrations took place, with many students imprisoned. == Aftermath == On 7 April 1977, the anniversary of the event, students (including Omar Dabob and Muhammed Ben Saoud) were publicly executed in Benghazi, with anti-Gaddafi military officers executed later in the week.","t":"1976 Libyan protests (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Human_rights_in_Libya_under_Muammar_Gaddafi":{"pre":"This included extrajudicial killings, public executions, ethnic cleansing, and the torture of civilians.","hi":"During the Libyan Civil War in 2011, Gaddafi's forces killed allegedly unarmed protestors and indiscriminately bombed civilian areas, drawing condemnation from human rights organizations. == Student protests == On April 7, 1976, university students throughout Libya protested against human rights violations and authoritarian military control over all aspects of civilian lives.","post":"Protesters called for free and fair elections to take place and a more democratic system to be implemented in Libya.","t":"Human rights in Libya under Muammar Gaddafi (Wikipedia)","d":""},"http://countrystudies.us/libya/76.htm":{"pre":"Since that time, there have been intermittent reports of student rebelliousness.","hi":"In April 1984, for instance, two students at Al Fatah University were publicly hanged.","post":"Apparently in revenge, two revolutionary committee members were found murdered on campus.","t":"Libya - OPPOSITION TO QADHAFI","d":"1987"}},"mk-hang-1983-eng":{"https://ar.wikipedia.org/wiki/%D8%A7%D9%86%D8%AA%D9%87%D8%A7%D9%83%D8%A7%D8%AA_%D8%AD%D9%82%D9%88%D9%82_%D8%A7%D9%84%D8%A5%D9%86%D8%B3%D8%A7%D9%86_%D9%81%D9%8A_%D8%B9%D9%87%D8%AF_%D8%A7%D9%84%D9%82%D8%B0%D8%A7%D9%81%D9%8A":{"pre":"محمد محمد حفاف، 7 أبريل 1983، طرابلس.","hi":"طالب اعتقل في إبريل 1973 بتهمة الانتماء لحزب التحرير الإسلامي رغم عدم وجود أدلة كافية، وبعد عشر سنوات في 7 إبريل 1983 أعدم شنقاً في كلية الهندسة بطرابلس.","post":"عبد الله المسلاتي، إبريل 1984، طرابلس.","t":"انتهاكات حقوق الإنسان في عهد القذافي (Arabic Wikipedia)","d":""}},"mk-hang-1984-agri":{"https://ar.wikipedia.org/wiki/%D8%A7%D9%86%D8%AA%D9%87%D8%A7%D9%83%D8%A7%D8%AA_%D8%AD%D9%82%D9%88%D9%82_%D8%A7%D9%84%D8%A5%D9%86%D8%B3%D8%A7%D9%86_%D9%81%D9%8A_%D8%B9%D9%87%D8%AF_%D8%A7%D9%84%D9%82%D8%B0%D8%A7%D9%81%D9%8A":{"pre":"طالب تم اعتقاله بعد أعمال الشغب في كلية الهندسة، نوفمبر '80.","hi":"تم إعدامه شنقاً في كلية الزراعة بطرابلس.","post":"مصطفى رزان النويري إبريل 1984.","t":"انتهاكات حقوق الإنسان في عهد القذافي (Arabic Wikipedia)","d":""},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000807600015-8":{"pre":"In‘a visit today to the sprawling campus, which has an eerie resemblance to American university campuses plastered with posters in the 1960s, questions about the previous week’s executions drew icy stares and a few reluctant confirmations.","hi":"One was from a fourth-year engineering student who sat on a stone bench in the Agriculture Square where the second gallows stood.","post":"The sec- ond student who was executed apparently had about it,” the engineering student said.","t":"HANGINGS IN TRIPOLI FOCUS ATENTION ON LIBYAN DISSENT","d":"1984-04-23"}},"mk-hang-1984":{"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000807600015-8":{"pre":"","hi":"\\ Declassified in Part - Saniiees Copy Approved for Release 2012/01/23 : CIA-RDP90-00965R000807600015-8 Se: ore snTeRe Ty ? | Declassified in Part - Sanitized Copy Approved for Release 2012/01/23 : CIA-RDP90-00965R000807600015-8 WASHINGTON POST 23 April 1984 Hangings in Tripoli Focus By Bob Woodward Washington Post Staff Writer TRIPOLI, Libya, April 22—A week ago today the Student Rev- olutionary Committee, which en- sures that Libyan leader Col.","post":"Muammar Qaddafi’s revolution- — ‘ary principles are scrupulously adhered to among Tripoli Uni- versity’s 27,000 students, an- nounced that two students would be publicly hanged for treason.","t":"HANGINGS IN TRIPOLI FOCUS ATENTION ON LIBYAN DISSENT","d":"1984-04-23"},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000807600013-0":{"pre":"…litary adventures in Africa— as in Chad, where he has about 6,000 troops—and his attempts to overthrow enemies in Eqypt and Libya with Tunisia, Algeria, Syria, Eqypt or Sudan, have, in the words of one Libyan official, “cost billions and got us nowhere.” The internal repression has left a deep mark.","hi":"The public hangings of two students for treason at Tripoli University on April 16 contributed - to the anti-Qaddafi demonstration at : the Libyan Embassy“in London the next day.","post":"It was at that demonstra- tion that a British’ policewoman was killed by shots fired from the build- ing and 11 other persons were | wounded.","t":"QADDAFI'S AUTHORITY SAID TO BE WEAKENING","d":"1984-04-29"}},"mk-daghis-1980":{"https://archive.org/details/jprs-report_jprs-76102":{"pre":"Now Qadhdhafi's regime has added still another crime to the list of acts of physical liquidation which it has relied upon as an official policy and which was announced personally by Qadhdhafi in a public speech.","hi":"This crime was the murder of attorney ‘Amir al-Tahir al-Daghis after he was arrested at his place of residence in the city of Tripoli on Sunday, 24 February 1980.","post":"The body of the martyr was handed over to his relatives in a sealed box. ‘They were allowed to see only his face for the purpose of identifying him.","t":"Near East/North Africa Report No. 2153","d":"1980-07-23"},"https://archive.org/details/jprs-report_jprs-76460":{"pre":"There are some definite facts discovered by Amnesty international about the repressive methods governing Libya, which indicate the arrest of hundreds of Libyans--civilians and military persoanel--since February, simultaneous with wholesale overseas assassination operations against al-Qadhdhafi's opponents.","hi":"Thus Lawyer Amin Dayfin died in prison under obscure circumstances after 3 days of torture, and masses of Libyans attended his funeral procession.","post":"Al- Qadhdhafi's reaction was to arrest two more prominent lawyers, Muhammad Sajir and Muhammad Banuna, who in turn met their end at the hands of the popular security committees.","t":"Near East/North Africa Report No. 2185","d":"1980-09-22"}},"mk-zirti-1984":{"https://archive.org/details/micro_IA1176909_0432":{"pre":"LIBYA ‘Traitor Recruited’ By U.S.","hi":"Intelligence Hanged LD041 302 Tripoli Domestic Service in Arabic 1230 GM1 4 Jun 8&4 [Text] Confirming the people’s authority and realizing direct democracy, the Basic People’s Congress of Tanzim held an emergency session this morning, Monday, 4 June, to implement the decision of the Basic People’s Congress of Tanzim dated 14 May 1984 to physically destroy the terrorists of the Muslim Brotherhood, agents of America.","post":"During the session the confes- sions of the criminal traitor Muhammad Sa’‘id ash-Shabani were read to the congress.","t":"FBIS Daily Report: Middle East & Africa, Vol. V No. 109, 5 June 1984","d":"1984-06-05"}},"bt-2011-fateh":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Initially, a governmental spokesman stated that all was safe and well within the city and that loyalist forces remained in control of Tripoli.","hi":"Later, he stated that \"armed militants\" had \"escaped into some neighbourhoods\", causing \"a few scuffles\", but the governmental forces \"dealt with it within a half-hour, and it is now calm.\" A group of students of the Fateh University who were sympathetic to the rebellion rose up against the armed guards that patrolled the perimeter and the snipers in the taller buildings and seized control of the university during the night. === 21 August === Rebel forces began advancing east from Zawiya towards Tripoli; they took the town of Joudaim, east of Zawiya, meeting only light resistance from loyalist forces.","post":"Next, the town of Al Maya just west of Tripoli was taken.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-janzour":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"They also took control of a Tripoli mobile-telephone company.","hi":"Rebel forces advancing from Zawiya entered the Janzur suburb of Tripoli during the evening, seemingly facing no resistance as they passed through the western suburbs headed for the city centre, greeted by cheering crowds waving the rebels tricolour flag.","post":"Shortly after taking Janzur, rebels from the Tripoli Brigade took control of the Gheryan bridge, considered the western entrance to Tripoli proper, and entered the Syhia district and began clearing it.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-west":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Rebel forces advancing from Zawiya entered the Janzur suburb of Tripoli during the evening, seemingly facing no resistance as they passed through the western suburbs headed for the city centre, greeted by cheering crowds waving the rebels tricolour flag.","hi":"Shortly after taking Janzur, rebels from the Tripoli Brigade took control of the Gheryan bridge, considered the western entrance to Tripoli proper, and entered the Syhia district and began clearing it.","post":"They took Hay al Andalus area shortly after and immediately advanced into the Gergraish area of Central Tripoli.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-rixos":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"…al-Islam Gaddafi had been captured and the UK representative of the NTC repeated the claim to the satisfaction of the International Criminal Court which stated that they would be contacting the NTC to make arrangements for him to be handed over, so that he may face trial for crimes against humanity.","hi":"However, early on 23 August, Saif al-Islam appeared to be quite obviously not in rebel custody as he appeared at the Rixos Al Nasr hotel where several foreign journalists were located and offered to give reporters a tour of loyalist-controlled areas.","post":"Al Jazeera also reported in its video that Muhammad Gaddafi, Muammar Gaddafi's oldest son, had handed himself over to rebel forces.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-salaheddin":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"…n a NATO air-strike on 29 August, while traveling to Bani Walid, but there was no independent confirmation of this and NATO stated they had no information on his fate. === 27 August === During the night, rebel forces were able to secure Qasr bin Ghashir, a village near Tripoli International Airport.","hi":"They also claimed that the loyalist-held area in greater Tripoli had been reduced to just one compound. === 28 August === In the final actions of the battle, NLA forces launched an attack on the last remaining loyalist base in Salaheddin, a suburb 5 kilometres (3.1 miles) south of Tripoli and took it after seven hours of fighting. == Operation Mermaid Dawn plans and aims == In the weeks following the battle, the rebels' plans to take Tripoli were revealed.","post":"The National Transitional Council had been in contact with rebel cells inside Tripoli, including employees of the Gaddafi government sympathetic to the opposition's cause.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-1911-ainzara":{"https://en.wikipedia.org/wiki/Battle_of_Ain_Zara":{"pre":"","hi":"The Battle of Ain Zara was fought in December 1911 during the Italo-Turkish War between the Kingdom of Italy and Ottoman Empire forces for the control of the oasis of Ain Zara, near Tripoli in modern Libya, where the Ottomans had established a fortified base. == Background == In October 1911, after the outbreak of the Italo-Turkish War, Italian troops landed in Tripolitania and captured Tripoli.","post":"Before being able to complete the occupation of Tripoli, the Italian forces needed to eliminate the threat posed by Ain Zara, an oasis 8 km south of Tripoli, which the Ottoman forces (including native Arab forces) had turned into a well-fortified position, garrisoned by 8,000 men with a battery of e…","t":"Battle of Ain Zara (Wikipedia)","d":""}},"bt-1911-sharshatt":{"https://en.wikipedia.org/wiki/Battle_and_massacre_at_Shar_al-Shatt":{"pre":"The situation only stabilized around 5 p.m., with the arrival of a battalion of the 82nd Infantry Regiment, and two battalions of sailors formed by the landing companies of the Sicilia, the Sardegna, the Re Umberto and the Carlo Alberto, supported by a 75 mm landing battery already deployed at Bu Meliana.","hi":"Shar al-Shatt was only reoccupied at sunset by the infantrymen of the 82nd Infantry Regiment supported by the remains of the 4th and 5th Companies Bersaglieri (reduced to only 57 survivors in two platoons), after a house-to-house fight. == The Battle of Bu-Meliana, 26 October == Three days after the Battle of Shar al-Shatt, on October 26, at 5 am, and with all available forces, the Ottomans attacked Tripoli again, engaging the entire southeastern sector.","post":"Despite limited breakthroughs to the west, the Italian line managed to hold, mainly thanks to artillery cover and counterattacks by reinforcements coming from the city (during these clashes, among others, the recipient of the Gold Medal of Military Valor, Riccardo Grazioli Lante della Rovere was killed).","t":"Battle and massacre at Shar al-Shatt (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Italo-Turkish_War":{"pre":"The force was able to capture Tripoli, Tobruk, Derna, Bengasi, and Homs between 3 and 21 October.","hi":"However, the Italians suffered a defeat at Shar al-Shatt, with at least 21 officers and 482 soldiers dead.","post":"The Italians executed 400 women and 4,000 men through firing squads and hanging in retaliation.","t":"Italo-Turkish War (Wikipedia)","d":""}},"bt-1943-castelbenito":{"https://en.wikipedia.org/wiki/RAF_Castel_Benito":{"pre":"It was called RAF Castel Benito by the Allies.","hi":"RAF Castel Benito (later RAF Idris) was a Royal Air Force station near Tripoli in Libya between 1943 and 1966. == History == 1934: A Regia Aeronautica (Italian Air Force) airfield was created on the south edge of Italian Tripoli.","post":"It was the operational base for the \"15° Stormo da bombardamento\" with Savoia Marchetti SM.","t":"RAF Castel Benito (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Tripoli_International_Airport":{"pre":"The first international flights were to Rome, Tunis, and Malta.","hi":"In 1939, a flight from Rome to Ethiopia and Somalia was one of the first intercontinental flights. === Post-war === In the early hours of 23 January 1943, the Eighth Army entered Tripoli and captured Castel Benito Airport.","post":"By then, it had been destroyed from Allied aerial raids.","t":"Tripoli International Airport (Wikipedia)","d":""}},"bt-1986-bab-gunfight":{"https://www.cia.gov/readingroom/document/cia-rdp91b00874r000200120013-4":{"pre":"fell ee trl ed 1 | Sanitized Copy Approved for Release 2011/09/13 : CIA-RDP91B00874R000200120013-4 STAT _ Current listing of: T1333:3 04/23/86 01:42 Page: 1 Slug:UK: TIMES REPORTS LIBYA RULED Date: 04/23/86.","hi":"01:38:22 Category:FBIS Story: 032 FOR OFFICIAL US AT LD230556 LONDON THE TIMES IN ENGLISH 23 APR 86 P l (\"JUNTA SHARES LIBYA POWER WITH AL-QADHDHAFI\" BY ROBERT FISK, TRIPOLI) (TEXT) A FIVE-MAN JUNTA OF MILITARY OFFICERS APPEARS TO BE GOVERNING LIBYA IN THE AFTERMATH OF THE AMERICAN AIR RAID -- A COLLECTIVE LEADERSHIP WHICH INCLUDES COLONEL AL-QADHDHAFI AS THE NATION'S NOMINAL LEADER BUT WHICH HAS DIVESTED HIM OF HIS EXCLUSIVE CONTROL OVER THE COUNTRY.","post":"THE INSPECTOR GENERAL OF THE LIBYAN ARMY AND THE COMMANDER- IN- CHIEF OF THE ARMED FORCES ARE BELIEVED TO BE MEMBERS OF THE NEW a ADMINISTRATION IN WHICH COLONEL AL-QADHDHAFI NOW PERFORMS THE TASKS OF A FIGUREHEAD RATHER THAN THE SOLE POLITICAL AND MILITARY LEADER SINCE THE AIR RAIDS, COLONEL AL-QAD…","t":"(JUNTA SHARES LIBYA POWER WITH AL-QADHDHAFI BY ROBERT FISK, TRIPOLI)","d":"1986-04-23"},"https://www.cia.gov/readingroom/document/cia-rdp91b00874r000100160006-9":{"pre":"…any fled the major towns to avoid the eae of subsequent air strikes. t at most 25X1 the Libyans are indifferent to the fate of the regime, 20X1 -- skirmishes between regular troops and the radical Revolutionary Committees--Qadhafi's primary source of support--in the immediate aftermath of the raids.","hi":"In addition a battalion of troops apparently mutinied at Tarhuna--outside Tripoli--on 16 April; it was put down by loyal air force units.","post":"25X1 Qadhafi is still in control of the regime, but he is taking steps to shore up his support in the armed forces and to reconsolidate his grip on power.","t":"TALKING POINTS FOR THE ADDI THE LIBYAN DOMESTIC SITUATION","d":"2011-08-17"},"https://www.cia.gov/readingroom/document/cia-rdp05-01559r000400410035-2":{"pre":"His appearance on television has ended speculation about his own personal safety following the bomb attack on his home which killed his adopted daughter and injured two of his sons.","hi":"Yesterday, there was also speculation that a coup attempt against Col al-Qadhdhafi was under way with reports on gun fire and unexplained disturbances in Tripoli, but the Libyans have firmly denied this.","post":"To find out whether the Libyan leader’s television address has defused any of the tension inside libya, Mann Price spoke a short time ago to one of the BBC’s correspondents in Tripoli, David Willie. [Begin recording] [Willie] Well, it had the curious and absolutely immediate effect of causing some d…","t":"AL-QADHDHAFI ADDRESSES NATION 16 APRIL","d":"1986-04-16"},"https://www.cia.gov/readingroom/document/cia-rdp05-01559r000400470001-3":{"pre":"…ts, skirmishes fuel tension in Tripoli Qaddafi’s failure to show up at news conference sparks rumors By the Associated Press Tripoli, Libya The atmosphere in the Libyan capital remained tense Wednesday, amid conflicting reports about alleged re- newed United States attacks and uncertainty about Col.","hi":"Muammar Qaddafi’s whereabouts and condition. | Libyan officials claimed that anti-aircraft fire that | broke out for a half-hour in Tripoli yesterday was aimed at a US reconnaissance sania aes Tadlo ase claimed that US jets seeeseeeeweesnenscmeenens raided, but failed to hit, Japan has tightened se- targets in two areas 40 curity for next month’s miles outside Tripoli. — summit because of the In Washington, a Pen- tagon spokesman denied US attack on Libya.","post":"Jap- the Libyan claim, saying, @nese terrorists have “There is no US military ties with Libya.","t":"GADHAFI, TROUBLED BY SERIES OF SETBACKS, ACTS TO REPAIR THE DAMAGE","d":"1987-11-19"}},"mk-riots-1948":{"https://en.wikipedia.org/wiki/1945_anti-Jewish_riots_in_Tripolitania":{"pre":"The situation of Libyan Jews further escalated with the eruption of the 1948 Arab–Israeli War.","hi":"In June 1948, anti-Jewish rioters in Libya killed another 12 Jews and destroyed 280 Jewish homes.","post":"This time, however, the Libyan Jewish community had prepared to defend itself.","t":"1945 anti-Jewish riots in Tripolitania (Wikipedia)","d":""}},"mk-riots-1967":{"https://en.wikipedia.org/wiki/1967_Tripoli_pogrom":{"pre":"","hi":"The 1967 Tripoli pogrom was an anti-Jewish pogrom which took place in the Libyan city of Tripoli. == Events == Two major pogroms had occurred in Libya prior to the riots of 1967: One in 1945 which killed over 140 people and one in 1948 that killed 14.","post":"The 1967 riot broke out in response to the Six-Day War between Israel and the Arab world.","t":"1967 Tripoli pogrom","d":"2026-10-18"}},"mk-mechiya-1911":{"https://en.wikipedia.org/wiki/Massacres_in_the_Italo-Turkish_War":{"pre":"Some Arabs collaborated with the Italians, mainly in the city of Tripoli, but those in the interior of Libya largely supported the Turks due to their shared religion.","hi":"During the war Italian troops used indiscriminate violence many times to subdue the native civilians. == Sciara Sciat massacre == On 23 October 1911, Italian troops were attacked by a 10,000-strong Ottoman force while marching through the Mechiya oasis, at a place called Sciara Sciat.","post":"Some accounts stated that Turkish forces captured two companies of the Italian infantry in a nearby cemetery and massacred 503 men.","t":"Massacres in the Italo-Turkish War (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Italo-Turkish_War":{"pre":"","hi":"The Italo-Turkish War (Turkish: Trablusgarp Savaşı, \"Tripolitanian War\", Italian: Guerra di Libia, \"War of Libya\"), also known as the Turco-Italian War, was fought between the Kingdom of Italy and the Ottoman Empire from 29 September 1911 to 18 October 1912.","post":"As a result of this conflict, Italy captured coastal areas of the Ottoman Tripolitania Vilayet, of which the main sub-provinces were Fezzan (Turkish: Fizan), Cyrenaica (Turkish: Sirenayka), and Tripoli (Turkish: Trablusgarp) itself.","t":"Italo-Turkish War (Wikipedia)","d":""}},"mk-1945-janzur":{"https://en.wikipedia.org/wiki/1945_anti-Jewish_riots_in_Tripolitania":{"pre":"The 1945 anti-Jewish riots in Tripolitania were the most violent riots against Jews in North Africa in the 20th century.","hi":"From November 5 to November 7, 1945, more than 140 Jews were killed and many more injured in a pogrom in Tripolitania, then under British military occupation.","post":"38 Jews were killed in Tripoli from where the riots spread.","t":"1945 anti-Jewish riots in Tripolitania (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Janzur":{"pre":"…d from the Phoenician and Phoenician use abjad system (ABCD HWZ...)). === Historical overview === On March 6, 1912, the Italian forces became the first to use airships in war, as two dirigibles dropped bombs on Turkish troops and Libyan Mujahideen encamped at Janzour, from an altitude of 6,000 feet.","hi":"There was still a Jewish presence in Zanzur at the end of World War II at which time a local synagogue was burned down and Jews killed during a pogrom.","post":"Janzour became a Baladiyah that followed the Greater Tripoli Muhafazah, Janzur was part of Jafara District since 2001.","t":"Janzur (Wikipedia)","d":""}},"mk-1945-tajura":{"https://en.wikipedia.org/wiki/1945_anti-Jewish_riots_in_Tripolitania":{"pre":"Despite liberation from Fascist Italian and Nazi German influence in 1943, North African Jews kept suffering attacks.","hi":"Arab nationalists were incorporating effective propaganda efforts and on November 2, 1945, the anniversary of the Balfour Declaration, a wave of anti-Jewish rioting hit the cities of Aleppo (Syria), Cairo (Egypt) and, most severely, Tripoli. == The pogrom == Some of the worst anti-Jewish violence occurred following the liberation of North Africa by Allied troops.","post":"From November 5 to November 7, 1945, more than 140 Jews (including 36 children) were killed and hundreds more injured in the Tripoli pogrom.","t":"1945 anti-Jewish riots in Tripolitania (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Tajura":{"pre":"","hi":"Tajura (Arabic: تاجوراء, romanized: Tājūrā), also spelt Tajoura, is a town in north-western Libya, and baladiyah in the Tripoli Muhafazah, on the Mediterranean coast 23 kilometres (14 mi) east of Tripoli.","post":"From 2001 to 2007 Tajura was the capital of the Tajura wa Arba' District.","t":"Tajura (Wikipedia)","d":""}},"as-1912-janzur":{"https://en.wikipedia.org/wiki/Janzur":{"pre":"…hian (وخيعن), from the tribe of Houara, but today the city is considered far from tribalism, and mixed from several origins of Houara of sons of Gharyan and Mslath, Misrata and Tarhona and Orfeila, and the families of the tribe of Nafusa and the families of tribe of Zanata, and Arabs of Banu Dabbab.","hi":"Janzur is derived from the Latin word \"Censor\" (In old Latin, C pronounce, such as G, like Greek the ancestor of Latin, which C correspond to Γ (third letter), which Greek is derived from the Phoenician and Phoenician use abjad system (ABCD HWZ...)). === Historical overview === On March 6, 1912, the Italian forces became the first to use airships in war, as two dirigibles dropped bombs on Turkish troops and Libyan Mujahideen encamped at Janzour, from an altitude of 6,000 feet.","post":"There was still a Jewish presence in Zanzur at the end of World War II at which time a local synagogue was burned down and Jews killed during a pogrom.","t":"Janzur (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Italo-Turkish_War":{"pre":"The Libyan campaign ground to a stalemate by December 1911.","hi":"On 3 March 1912, 1,500 Libyan volunteers attacked Italian troops who were building trenches near Derna.","post":"The Italians, who were outnumbered but had superior weaponry, held the line.","t":"Italo-Turkish War (Wikipedia)","d":""}}};
